      "question": "Quels collèges comptent le plus de membres inscrits, en incluant ceux qui n’en ont aucun ?",
      "sql": "SELECT c.Name AS college, COUNT(m.Member_ID) AS nombre_membres\nFROM college AS c\nLEFT JOIN member AS m ON m.College_ID = c.College_ID\nGROUP BY c.College_ID, c.Name\nORDER BY nombre_membres DESC, college;"
    },
    {
      "question": "Quels membres ont obtenu au moins une fois le rang 1 dans une manche ?",
      "sql": "SELECT DISTINCT m.Member_ID, m.Name\nFROM member AS m\nJOIN round AS r ON r.Member_ID = m.Member_ID\nWHERE r.Rank_in_Round = 1\nORDER BY m.Name;"
    },
    {
      "question": "Pour chaque thème de décoration, quel est le nombre de participations et le rang moyen obtenu, en ne conservant que les thèmes ayant au moins deux participations ?",
      "sql": "SELECT Decoration_Theme AS theme,\n       COUNT(*) AS nombre_participations,\n       AVG(Rank_in_Round) AS rang_moyen\nFROM round\nGROUP BY Decoration_Theme\nHAVING COUNT(*) >= 2\nORDER BY nombre_participations DESC, theme;"
    }
  ]
}
